            )
            col_widths.append(w)

        # Box drawing characters
        top_border = '┌' + '┬'.join('─' * (w + 2) for w in col_widths) + '┐'
        mid_border = '├' + '┼'.join('─' * (w + 2) for w in col_widths) + '┤'
        bot_border = '└' + '┴'.join('─' * (w + 2) for w in col_widths) + '┘'

        # Box width for footer
        box_width = len(top_border)

        # Print top border
        print(top_border, file=out)

        # Print header row (centered)
        if self.headers:
            header_line = '│' + '│'.join(f' {col.center(w)} ' for col, w in zip(cols, col_widths)) + '│'
            print(header_line, file=out)
            # Print type row (centered)
            type_line = '│' + '│'.join(f' {(types[i] if i < len(types) else "varchar").center(w)} ' for i, w in enumerate(col_widths)) + '│'
            print(type_line, file=out)

        # Middle border
        print(mid_border, file=out)

        # Print data rows
        n_total = len(formatted_rows)
        if n_total <= self.maxrows + 3:
            rows_to_print = list(range(n_total))
            dots_at = None
        else:
            # Show first maxrows/2 and last maxrows/2
            half = self.maxrows // 2
            rows_to_print = list(range(half)) + None + list(range(n_total - half, n_total))
            dots_at = half

        def print_data_row(row_data):
            cells = []
            for i, val in enumerate(row_data):
                w = col_widths[i]
                dtype = types[i] if i < len(types) else 'varchar'
                if self._is_numeric_type(dtype) and val != self.null_value:
                    # Right align
                    cell = f' {val.rjust(w)} '
                else:
                    # Left align
                    cell = f' {val.ljust(w)} '
                cells.append(cell)
            print('│' + '│'.join(cells) + '│', file=out)

        def print_dots_row():
            cells = []
            for w in col_widths:
                cell = f' {"·".rjust(w)} '
                cells.append(cell)
            print('│' + '│'.join(cells) + '│', file=out)

        if dots_at is None:
            for row_data in formatted_rows:
                print_data_row(row_data)
        else:
            half = self.maxrows // 2
            for i in range(half):
                print_data_row(formatted_rows[i])
            for _ in range(3):
                print_dots_row()
            for i in range(n_total - half, n_total):
                print_data_row(formatted_rows[i])

        # Bottom border
        print(bot_border, file=out)

        # Footer for large result sets
        if n_total > self.maxrows + 3:
            content = f'{n_total} rows ({self.maxrows} shown)'
            total_pad = box_width - 2 - len(content)
            if total_pad % 2 == 0:
                left = total_pad // 2 + 1
                right = total_pad // 2 - 1
            else:
                left = (total_pad + 1) // 2
                right = total_pad // 2
            print(' ' * left + content + ' ' * right, file=out)

    def _print_csv(self, cols, rows, types, out):
        """Print in CSV format."""
        import csv
        import io

        writer = csv.writer(out, lineterminator='\n')
        if self.headers:
            writer.writerow(cols)
        for row in rows:
            writer.writerow([self._format_val(v, types[i] if i < len(types) else 'varchar') 
                           for i, v in enumerate(row)])

    def _print_json(self, cols, rows, types, out):
        """Print in JSON format."""
        import json
        result = []
        for row in rows:
            obj = {}
            for i, col in enumerate(cols):
                val = row[i]
                dtype = types[i] if i < len(types) else 'varchar'
                if val is None:
                    obj[col] = None
                elif self._is_numeric_type(dtype):
                    obj[col] = val
                elif isinstance(val, bool):
                    obj[col] = val
                elif isinstance(val, (int, float)):
                    obj[col] = val
                else:
                    obj[col] = str(val)
            result.append(obj)
        print(json.dumps(result), file=out)

    def _print_jsonlines(self, cols, rows, types, out):
        """Print in JSONL format."""
        import json
        for row in rows:
            obj = {}
            for i, col in enumerate(cols):
                val = row[i]
                if val is None:
                    obj[col] = None
                elif isinstance(val, (bool, int, float)):
                    obj[col] = val
                else:
                    obj[col] = str(val)
            print(json.dumps(obj), file=out)

    def _print_line(self, cols, rows, types, out):
        """Print in line format (key=value)."""
        max_col_len = max(len(c) for c in cols) if cols else 0
        for row in rows:
            for i, col in enumerate(cols):
                val = self._format_val(row[i], types[i] if i < len(types) else 'varchar')
                print(f'{col.rjust(max_col_len)} = {val}', file=out)
            if len(rows) > 1:
                print('', file=out)

    def _print_list(self, cols, rows, types, out):
        """Print in list format."""
        if self.headers:
            print(self.separator.join(cols), file=out)
        for row in rows:
            vals = [self._format_val(v, types[i] if i < len(types) else 'varchar') for i, v in enumerate(row)]
            print(self.separator.join(vals), file=out)

    def _print_column(self, cols, rows, types, out):
        """Print in column format."""
        # Calculate widths
        col_widths = []
        for i, col in enumerate(cols):
            max_val = max((len(self._format_val(r[i], types[i] if i < len(types) else 'varchar')) for r in rows), default=0)
            col_widths.append(max(len(col), max_val))

        if self.headers:
            print('  '.join(c.ljust(w) for c, w in zip(cols, col_widths)).rstrip(), file=out)
            print('  '.join('-' * w for w in col_widths).rstrip(), file=out)

        for row in rows:
            vals = [self._format_val(row[i], types[i] if i < len(types) else 'varchar') for i in range(len(cols))]
            print('  '.join(v.ljust(w) for v, w in zip(vals, col_widths)).rstrip(), file=out)

    def _print_markdown(self, cols, rows, types, out):
        """Print in Markdown table format."""
        col_widths = []
        for i, col in enumerate(cols):
            dtype = types[i] if i < len(types) else 'varchar'
            max_val = max((len(self._format_val(r[i], dtype)) for r in rows), default=0)
            col_widths.append(max(len(col), max_val, 3))

        # Header
        if self.headers:
            print('| ' + ' | '.join(c.ljust(w) for c, w in zip(cols, col_widths)) + ' |', file=out)
            # Separator
            seps = []
            for i, w in enumerate(col_widths):
                dtype = types[i] if i < len(types) else 'varchar'
                if self._is_numeric_type(dtype):
                    seps.append('-' * (w-1) + ':')
                else:
                    seps.append('-' * w)
            print('|' + '|'.join(s for s in seps) + '|', file=out)

        for row in rows:
            vals = []
            for i, v in enumerate(row):
                dtype = types[i] if i < len(types) else 'varchar'
                formatted = self._format_val(v, dtype)
                if self._is_numeric_type(dtype):
                    vals.append(formatted.rjust(col_widths[i]))
                else:
                    vals.append(formatted.ljust(col_widths[i]))
            print('| ' + ' | '.join(vals) + ' |', file=out)

    def _print_box(self, cols, rows, types, out):
        """Print in box format (like ASCII table)."""
        col_widths = []
        for i, col in enumerate(cols):
            dtype = types[i] if i < len(types) else 'varchar'
            max_val = max((len(self._format_val(r[i], dtype)) for r in rows), default=0)
            col_widths.append(max(len(col), max_val, 1))

        def make_border(left, mid, right, fill):
            return left + mid.join(fill * (w + 2) for w in col_widths) + right

        top = make_border('┌', '┬', '┐', '─')
        mid = make_border('├', '┼', '┤', '─')
        bot = make_border('└', '┴', '┘', '─')

        print(top, file=out)
        if self.headers:
            print('│' + '│'.join(f' {c.center(w)} ' for c, w in zip(cols, col_widths)) + '│', file=out)
            print(mid, file=out)

        for row in rows:
            vals = [self._format_val(row[i], types[i] if i < len(types) else 'varchar') for i in range(len(cols))]
            print('│' + '│'.join(f' {v.ljust(w)} ' for v, w in zip(vals, col_widths)) + '│', file=out)

        print(bot, file=out)

    def _print_table(self, cols, rows, types, out):
        """Print in table format (ASCII)."""
        col_widths = []
        for i, col in enumerate(cols):
            dtype = types[i] if i < len(types) else 'varchar'
            max_val = max((len(self._format_val(r[i], dtype)) for r in rows), default=0)
            col_widths.append(max(len(col), max_val))

        sep = '+' + '+'.join('-' * (w + 2) for w in col_widths) + '+'

        print(sep, file=out)
        if self.headers:
            print('|' + '|'.join(f' {c.ljust(w)} ' for c, w in zip(cols, col_widths)) + '|', file=out)
            print(sep, file=out)

        for row in rows:
            vals = [self._format_val(row[i], types[i] if i < len(types) else 'varchar') for i in range(len(cols))]
            print('|' + '|'.join(f' {v.ljust(w)} ' for v, w in zip(vals, col_widths)) + '|', file=out)

        print(sep, file=out)

    def _print_ascii(self, cols, rows, types, out):
        """Print in ASCII format."""
        for col in cols:
            print(col, file=out)
        for row in rows:
            for i, v in enumerate(row):
                print(self._format_val(v, types[i] if i < len(types) else 'varchar'), file=out)

    def _print_quote(self, cols, rows, types, out):
        """Print in quote format."""
        if self.headers:
            print(self.separator.join(f"'{c}'" for c in cols), file=out)
        for row in rows:
            vals = []
            for i, v in enumerate(row):
                formatted = self._format_val(v, types[i] if i < len(types) else 'varchar')
                dtype = types[i] if i < len(types) else 'varchar'
                if self._is_numeric_type(dtype) and v is not None:
                    vals.append(formatted)
                else:
                    vals.append(f"'{formatted}'")
            print(self.separator.join(vals), file=out)

    def _print_html(self, cols, rows, types, out):
        """Print in HTML format."""
        print('<TABLE BORDER=1>', file=out)
        if self.headers:
            print('<TR>' + ''.join(f'<TH>{c}</TH>' for c in cols) + '</TR>', file=out)
        for row in rows:
            vals = [self._format_val(row[i], types[i] if i < len(types) else 'varchar') for i in range(len(cols))]
            print('<TR>' + ''.join(f'<TD>{v}</TD>' for v in vals) + '</TR>', file=out)
        print('</TABLE>', file=out)

    def handle_dot_command(self, line):
        """Handle dot commands like .help, .mode, etc."""
        parts = shlex.split(line[1:])  # Remove leading dot
        if not parts:
            return

        cmd = parts[0].lower()
        args = parts[1:]

        if cmd == 'help':
            self._cmd_help(args)
        elif cmd == 'quit' or cmd == 'exit':
            sys.exit(0)
        elif cmd == 'mode':
            if args:
                mode = args[0].lower()
                mode_map = {
                    'csv': OutputMode.CSV,
                    'json': OutputMode.JSON,
                    'jsonlines': OutputMode.JSONLINES,
                    'line': OutputMode.LINE,
                    'list': OutputMode.LIST,
                    'column': OutputMode.COLUMN,
                    'markdown': OutputMode.MARKDOWN,
                    'box': OutputMode.BOX,
                    'table': OutputMode.TABLE,
                    'ascii': OutputMode.ASCII,
                    'quote': OutputMode.QUOTE,
                    'html': OutputMode.HTML,
                    'duckbox': OutputMode.DUCKBOX,
                }
                if mode in mode_map:
                    self.mode = mode_map[mode]
        elif cmd == 'headers':
            if args:
                self.headers = args[0].lower() in ('on', '1', 'true')
        elif cmd == 'echo':
            if args:
                self.echo = args[0].lower() in ('on', '1', 'true')
        elif cmd == 'bail':
            if args:
                self.bail = args[0].lower() in ('on', '1', 'true')
        elif cmd == 'nullvalue':
            if args:
                self.null_value = args[0]
        elif cmd == 'separator':
            if args:
                self.separator = args[0]
        elif cmd == 'maxrows':
            if args:
                try:
                    self.maxrows = int(args[0])
                except:
                    pass
        elif cmd == 'timer':
            if args:
                self.timer = args[0].lower() in ('on', '1', 'true')
        elif cmd == 'version':
            out = self.get_output()
            print(f'DuckDB {VERSION_FULL}', file=out)
            print(COMPILER, file=out)
        elif cmd == 'tables':
            cols, rows, _ = self.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
            if rows:
                for row in rows:
                    print(row[0], file=self.get_output())
        elif cmd == 'databases':
            self.run_sql("SELECT 656 AS seq, 'memory' AS name, NULL AS file")
        elif cmd == 'show':
            self._cmd_show()
        elif cmd == 'output':
            if args:
                try:
                    self.output_file = open(args[0], 'w')
                except Exception as e:
                    print(f'Error: {e}', file=sys.stderr)
            else:
                if self.output_file:
                    self.output_file.close()
                    self.output_file = None
        elif cmd == 'read':
            if args:
                self._run_file(args[0])
        elif cmd == 'print':
            print(' '.join(args), file=self.get_output())
        elif cmd == 'cd':
            if args:
                try:
                    os.chdir(args[0])
                except Exception as e:
                    print(f'Error: {e}', file=sys.stderr)
        elif cmd in ('columns', 'multiline', 'rows', 'singleline'):
            pass  # Ignore rendering mode switches
        elif cmd == 'about':
            print('DuckDB is a high-performance analytical database system.', file=self.get_output())
        else:
            print(f'Error: unknown command or invalid arguments: ".{cmd}". Enter ".help" for help', file=sys.stderr)

