    def _cmd_show(self):
        """Show current settings."""
        out = self.get_output()
        settings = [
            ('echo', 'on' if self.echo else 'off'),
            ('headers', 'on' if self.headers else 'off'),
            ('mode', self.mode),
            ('nullvalue', repr(self.null_value)),
            ('output', 'stdout' if not self.output_file else self.output_file.name),
            ('separator', repr(self.separator)),
        ]
        for name, val in settings:
            print(f'{name}: {val}', file=out)

    def run_sql(self, sql):
        """Execute a SQL statement and print results."""
        sql = sql.strip()
        if not sql:
            return True

        if sql.startswith('.'):
            self.handle_dot_command(sql)
            return True

        try:
            # Special handling for DuckDB-specific commands
            if sql.upper().startswith('SELECT VERSION()'):
                out = self.get_output()
                if self.mode == OutputMode.CSV:
                    if self.headers:
                        print('"version"()', file=out)
                    print(f'{VERSION}', file=out)
                else:
                    cols = ['"version"()']
                    rows = [(VERSION,)]
                    types = ['varchar']
                    self.print_results(cols, rows, types)
                return True

            cursor = self.conn.execute(sql)

            if cursor.description is None:
                return True

            cols = [d[0] for d in cursor.description]
            rows = cursor.fetchall()

            # Infer types from first row
            types = []
            for i in range(len(cols)):
                if rows:
                    types.append(infer_type_from_value(rows[0][i]))
                else:
                    types.append('varchar')

            self.print_results(cols, rows, types)
            return True

        except sqlite3.Error as e:
            print(f'Error: {e}', file=sys.stderr)
            if self.bail:
                sys.exit(1)
            return False
        except Exception as e:
            print(f'Error: {e}', file=sys.stderr)
            return False

    def _run_file(self, filename):
        """Execute SQL from a file."""
        try:
            with open(filename, 'r') as f:
                sql = f.read()
            self.run_sql_batch(sql)
        except FileNotFoundError:
            print(f'Error: Cannot open "{filename}"', file=sys.stderr)

    def run_sql_batch(self, sql_text):
        """Execute multiple SQL statements."""
        # Split by semicolons (basic approach)
        statements = []
        current = []
        in_string = False
        string_char = None

        for char in sql_text:
            if in_string:
                current.append(char)
                if char == string_char:
                    in_string = False
            elif char in ('"', "'"):
                in_string = True
                string_char = char
                current.append(char)
            elif char == ';':
                current.append(char)
                stmt = ''.join(current).strip()
                if stmt and stmt != ';':
                    statements.append(stmt[:-1].strip())  # Remove trailing semicolon
                current = []
            else:
                current.append(char)

        if current:
            stmt = ''.join(current).strip()
            if stmt:
                statements.append(stmt)

        for stmt in statements:
            if stmt.startswith('.'):
                self.handle_dot_command(stmt)
            elif stmt:
                if self.echo:
                    print(stmt, file=self.get_output())
                self.run_sql(stmt)

    def run_interactive(self):
        """Run in interactive mode."""
        print(f'v{VERSION} ({TARGET_CODENAME}) {TARGET_SOURCE_ID}', file=sys.stderr)

        while True:
            try:
                line = input('D ')
                if line.strip():
                    if line.strip().startswith('.'):
                        self.handle_dot_command(line.strip())
                    else:
                        self.run_sql(line)
            except EOFError:
                break
            except KeyboardInterrupt:
                print('^C', file=sys.stderr)


