def main():
    args = sys.argv[1:]
    prog_name = sys.argv[0]

    cli = DuckDBCLI()
    db_path = ':memory:'
    run_commands = []
    init_file = None
    cmd_before = []
    readonly = False
    force_interactive = False
    no_stdin = False
    no_init = False
    run_file = None

    i = 0
    while i < len(args):
        arg = args[i]

        if arg in ('-h', '-help', '--help'):
            print_help(prog_name)
            sys.exit(0)
        elif arg in ('-version', '--version'):
            print(VERSION_FULL)
            sys.exit(0)
        elif arg in ('-c', '-s'):
            i += 1
            if i < len(args):
                run_commands.append(args[i])
            else:
                print(f'Missing Argument Error: Argument \'{arg}\' needs 1 arguments, but got 0', file=sys.stderr)
                sys.exit(1)
        elif arg == '-csv':
            cli.mode = OutputMode.CSV
        elif arg == '-json':
            cli.mode = OutputMode.JSON
        elif arg == '-jsonlines':
            cli.mode = OutputMode.JSONLINES
        elif arg == '-line':
            cli.mode = OutputMode.LINE
        elif arg == '-list':
            cli.mode = OutputMode.LIST
        elif arg == '-column':
            cli.mode = OutputMode.COLUMN
        elif arg == '-markdown':
            cli.mode = OutputMode.MARKDOWN
        elif arg == '-box':
            cli.mode = OutputMode.BOX
        elif arg == '-table':
            cli.mode = OutputMode.TABLE
        elif arg == '-ascii':
            cli.mode = OutputMode.ASCII
        elif arg == '-quote':
            cli.mode = OutputMode.QUOTE
        elif arg == '-html':
            cli.mode = OutputMode.HTML
        elif arg == '-header':
            cli.headers = True
        elif arg == '-noheader':
            cli.headers = False
        elif arg == '-echo':
            cli.echo = True
        elif arg == '-bail':
            cli.bail = True
        elif arg == '-readonly':
            readonly = True
        elif arg == '-interactive':
            force_interactive = True
        elif arg == '-no-stdin':
            no_stdin = True
        elif arg == '-no-init':
            no_init = True
        elif arg == '-batch':
            pass  # batch mode
        elif arg == '-safe':
            cli.safe_mode = True
        elif arg == '-unsigned':
            pass  # unsigned extensions
        elif arg == '-unredacted':
            pass  # unredacted secrets
        elif arg in ('-f',):
            i += 1
            if i < len(args):
                run_file = args[i]
        elif arg in ('-init',):
            i += 1
            if i < len(args):
                init_file = args[i]
        elif arg in ('-cmd',):
            i += 1
            if i < len(args):
                cmd_before.append(args[i])
        elif arg in ('-nullvalue',):
            i += 1
            if i < len(args):
                cli.null_value = args[i]
        elif arg in ('-separator',):
            i += 1
            if i < len(args):
                cli.separator = args[i]
        elif arg in ('-newline',):
            i += 1
            if i < len(args):
                cli.newline = args[i]
        elif arg in ('-storage-version',):
            i += 1
            # Just skip, SQLite doesn't have this
        elif arg == '-format':
            # Format SQL from stdin
            sql = sys.stdin.read()
            print(sql)  # Just output as-is since we can't format
            sys.exit(0)
        elif arg.startswith('-format-file'):
            i += 1
            if i < len(args):
                try:
                    with open(args[i]) as f:
                        sql = f.read()
                    print(sql)
                except:
                    pass
            sys.exit(0)
        elif not arg.startswith('-'):
            db_path = arg
            i += 1
            # Rest are SQL commands
            if i < len(args):
                run_commands.extend(args[i:])
                break
        else:
            print(f'Error: Unknown option: {arg}', file=sys.stderr)

        i += 1

    # Connect to database
    cli.connect(db_path, readonly=readonly)

    # Run init file
    if not no_init and init_file:
        cli._run_file(init_file)

    # Run pre-commands
    for cmd in cmd_before:
        if cmd.strip().startswith('.'):
            cli.handle_dot_command(cmd.strip())
        else:
            cli.run_sql_batch(cmd)

    # Run main commands
    for cmd in run_commands:
        if cmd.strip().startswith('.'):
            cli.handle_dot_command(cmd.strip())
        else:
            cli.run_sql_batch(cmd)

    if run_commands or no_stdin:
        sys.exit(0)

    # Run file and exit
    if run_file:
        cli._run_file(run_file)
        sys.exit(0)

    # Interactive or stdin mode
    if force_interactive or sys.stdin.isatty():
        cli.run_interactive()
    else:
        # Read from stdin
        sql = sys.stdin.read()
        if sql.strip():
            cli.run_sql_batch(sql)


if __name__ == '__main__':
    main()
